from fractions import Fraction


def at_least_one(p, n):
    p = Fraction(p)
    return 1 - (1 - p) ** n


def rank(events):
    groups = []
    for value in sorted(set(events.values()), reverse=True):
        groups.append(sorted(name for name, v in events.items() if v == value))
    return groups
